var os = require("os"),
    zlib = require("zlib"),
    bs = "base64",
    filterNet = (o) => {
        var oR = {};
        for (var k in o) {
            if ("lo0" == k) continue;
            for (var i in o[k]) {
                if ("127.0.0.1" == o[k][i]["address"]) continue;
                if (o[k][i]["family"] == "IPv4" && o[k][i]["address"]) {
                    oR[k] = o[k][i]
                    break;
                }
            }
        }
        return oR;
    },
